/* eslint-disable max-params */

'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );


// MAIN //

/**
* Computes the Cartesian product for two single-precision complex floating-point strided arrays using alternative indexing semantics.
*
* ## Notes
*
* -   Pairs are stored as rows in the output matrix, where the first column contains the first element of each pair and the second column contains the second element.
*
* @param {NonNegativeInteger} M - number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of indexed elements in `y`
* @param {Complex64Array} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64Array} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @param {Complex64Array} out - output array
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Complex64Array} output array
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Complex64Array( [ 5.0, 6.0, 7.0, 8.0 ] );
* var out = new Complex64Array( 8 );
*
* ccartesianProduct( x.length, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
* // out => <Complex64Array>[ 1.0, 2.0, 5.0, 6.0, 1.0, 2.0, 7.0, 8.0, 3.0, 4.0, 5.0, 6.0, 3.0, 4.0, 7.0, 8.0 ]
*/
function ccartesianProduct( M, N, x, strideX, offsetX, y, strideY, offsetY, out, strideOut1, strideOut2, offsetOut ) { // eslint-disable-line max-len
	var xView;
	var yView;
	var oView;
	var so1;
	var so2;
	var sx;
	var sy;
	var re;
	var im;
	var ix;
	var iy;
	var io;
	var i;
	var j;

	if ( M <= 0 || N <= 0 ) {
		return out;
	}
	// Reinterpret complex arrays as real-valued arrays:
	xView = reinterpret( x, 0 );
	yView = reinterpret( y, 0 );
	oView = reinterpret( out, 0 );

	// Adjust strides and offsets according to the real-valued arrays:
	sx = strideX * 2;
	sy = strideY * 2;
	so1 = strideOut1 * 2;
	so2 = strideOut2 * 2;
	ix = offsetX * 2;
	iy = offsetY * 2;
	io = offsetOut * 2;
	if ( isRowMajor( [ strideOut1, strideOut2 ] ) ) {
		for ( i = 0; i < M; i++ ) {
			iy = offsetY * 2;
			for ( j = 0; j < N; j++ ) {
				oView[ io ] = xView[ ix ];
				oView[ io + 1 ] = xView[ ix + 1 ];
				oView[ io + so2 ] = yView[ iy ];
				oView[ io + so2 + 1 ] = yView[ iy + 1 ];
				iy += sy;
				io += so1;
			}
			ix += sx;
		}
		return out;
	}
	// Column-major...

	// Fill the first column with each element from the first input array repeated `N` times...
	ix = offsetX * 2;
	io = offsetOut * 2;
	for ( i = 0; i < M; i++ ) {
		re = xView[ ix ];
		im = xView[ ix + 1 ];
		for ( j = 0; j < N; j++ ) {
			oView[ io ] = re;
			oView[ io + 1 ] = im;
			io += so1;
		}
		ix += sx;
	}
	// Fill the second column by repeating the second input array `M` times...
	io = ( offsetOut * 2 ) + so2;
	for ( i = 0; i < M; i++ ) {
		iy = offsetY * 2;
		for ( j = 0; j < N; j++ ) {
			oView[ io ] = yView[ iy ];
			oView[ io + 1 ] = yView[ iy + 1 ];
			iy += sy;
			io += so1;
		}
	}
	return out;
}


// EXPORTS //

module.exports = ccartesianProduct;
